// Ferrite's strict literal-range diagnostic is not an E#### Rust type error.
// Keep it covered without misclassifying a configurable rustc lint as a hard
// compile-fail fixture (the shared oracle deliberately allows warnings).
export const associatedTypeDiagnosticCases = [
  ["associated deferred literal still checks overflow", "trait A{type Item;}struct S;impl A for S{type Item=u8;}fn f<T:A>(x:T::Item,t:T)->T::Item{x}fn main(){let x=f(256,S);}", "E_LITERAL"],
];
